import pytest

from bedrock_protocol import v1001, v2168, v2193

# generated by gophertunnel 6353c49:
# packet.MoveActorDelta{EntityRuntimeID: 2,
#   Flags: MoveActorDeltaFlagHasX | MoveActorDeltaFlagHasZ |
#          MoveActorDeltaFlagHasRotY | MoveActorDeltaFlagOnGround,
#   Position: {1, 0, 3}, Rotation: {0, 90, 0}}
V1001_MOVED = bytes.fromhex("0255000000803f0000404040")

# generated by gophertunnel 6353c49:
# packet.MoveActorDelta{EntityRuntimeID: 2}
V1001_EMPTY = bytes.fromhex("020000")

# generated by gophertunnel 6353c49:
# packet.MoveActorDelta{EntityRuntimeID: 2, Flags: MoveActorDeltaFlagOnGround}
V1001_ON_GROUND = bytes.fromhex("024000")

# generated by gophertunnel b8bd735:
# packet.MoveActorDelta{EntityRuntimeID: 2, PositionX: protocol.Option(float32(1)),
#   PositionZ: protocol.Option(float32(3)), RotationY: protocol.Option(float32(90)), OnGround: true}
V2168_MOVED = bytes.fromhex("02010000803f0001000040400001400001000000")

# generated by gophertunnel b8bd735:
# packet.MoveActorDelta{EntityRuntimeID: 2}
V2168_EMPTY = bytes.fromhex("0200000000000000000000")

GOLDENS = [
    pytest.param(
        v1001.MoveActorDeltaPacket(
            move_data=v1001.MoveActorDeltaData(
                runtime_id=2, header=1 | 4 | 16 | 64, new_position_x=1.0, new_position_z=3.0, rot_y=64
            )
        ),
        V1001_MOVED,
        id="v1001-moved",
    ),
    pytest.param(
        v1001.MoveActorDeltaPacket(move_data=v1001.MoveActorDeltaData(runtime_id=2)),
        V1001_EMPTY,
        id="v1001-empty",
    ),
    pytest.param(
        v1001.MoveActorDeltaPacket(move_data=v1001.MoveActorDeltaData(runtime_id=2, header=64)),
        V1001_ON_GROUND,
        id="v1001-on-ground-header-bit",
    ),
    pytest.param(
        v2168.MoveActorDeltaPacket(
            move_data=v2168.MoveActorDeltaData(
                runtime_id=2, new_position_x=1.0, new_position_z=3.0, rot_y=64, is_on_ground=True
            )
        ),
        V2168_MOVED,
        id="v2168-moved",
    ),
    pytest.param(
        v2168.MoveActorDeltaPacket(move_data=v2168.MoveActorDeltaData(runtime_id=2)),
        V2168_EMPTY,
        id="v2168-empty",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_move_actor_delta_is_packet_111(version):
    assert version.packets[111] is version.MoveActorDeltaPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_actor_delta_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_actor_delta_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_v2168_rejects_a_v1001_flags_word_body():
    with pytest.raises(ValueError, match="at byte"):
        v2168.MoveActorDeltaPacket.from_bytes(V1001_MOVED)


def test_v2193_appends_the_tick_count_to_the_body():
    older = v2168.MoveActorDeltaPacket(
        move_data=v2168.MoveActorDeltaData(runtime_id=2, new_position_x=1.0, is_on_ground=True)
    )
    newer = v2193.MoveActorDeltaPacket(
        move_data=v2193.MoveActorDeltaData(runtime_id=2, new_position_x=1.0, is_on_ground=True, ticks=7)
    )
    assert len(bytes(newer)) == len(bytes(older)) + 1


def test_v2193_tick_count_round_trips():
    packet = v2193.MoveActorDeltaPacket(
        move_data=v2193.MoveActorDeltaData(runtime_id=2, new_position_x=1.0, is_on_ground=True, ticks=7)
    )
    assert v2193.MoveActorDeltaPacket.from_bytes(bytes(packet)) == packet


def test_v2193_rejects_a_v2168_body_without_the_tick_count():
    with pytest.raises(ValueError, match="at byte"):
        v2193.MoveActorDeltaPacket.from_bytes(V2168_MOVED)
